//go:build ignore

package main

import (
	"fmt"
	"io"

	"github.com/RyuaNerin/go-krypto/internal/generators"
)

const (
	stepFilename = "has160_step.go"
	stepHeader   = `
// Code generated by generate_compress.go. DO NOT EDIT.

package has160

import (
	"encoding/binary"
	"math/bits"
)
`
	stepFooter = ``
)

func main() {
	generators.WriteBody(
		stepFilename,
		stepHeader,
		stepFooter,
		func(w io.Writer) {
			build(w)
		},
	)
}

func round(w io.Writer, r int) {
	fmt.Fprintf(w, "// Round %d\n", r+1)

	for j := range 20 {
		a := (5 - j%5) % 5
		step(w, r, a, (a+1)%5, (a+2)%5, (a+3)%5, (a+4)%5, j)
	}
}

// T   = (A <<< s1) + f(B, C, D) + E + X[l] + K
// E,D,C,B,A = D, C, (B <<< s2), A, T
func step(w io.Writer, r, a, b, c, d, e, j int) {
	fmt.Fprintf(
		w, "%s, %s = f%d(%s, %s, %s, %s, %s, x[%d], %d) // j = %d\n",
		reg[e], reg[b],
		r+1,
		reg[a], reg[b], reg[c], reg[d], reg[e],
		xt[r][j], s1[j],
		r*20+j,
	)
}

var reg = [5]string{"a", "b", "c", "d", "e"}

var (
	s1 = [20]int{5, 11, 7, 15, 6, 13, 8, 14, 7, 12, 9, 11, 8, 15, 6, 12, 9, 14, 5, 13}

	xt = [4][20]int{
		{18, 0, 1, 2, 3, 19, 4, 5, 6, 7, 16, 8, 9, 10, 11, 17, 12, 13, 14, 15},
		{18, 3, 6, 9, 12, 19, 15, 2, 5, 8, 16, 11, 14, 1, 4, 17, 7, 10, 13, 0},
		{18, 12, 5, 14, 7, 19, 0, 9, 2, 11, 16, 4, 13, 6, 15, 17, 8, 1, 10, 3},
		{18, 7, 2, 13, 8, 19, 3, 14, 9, 4, 16, 15, 10, 5, 0, 17, 11, 6, 1, 12},
	}
)

func build(w io.Writer) {
	fmt.Fprintln(
		w, `
func (ctx *has160ContextData) stepBlock(block *[BlockSize]byte) {
	x := [20]uint32{
		binary.LittleEndian.Uint32(block[0:]),
		binary.LittleEndian.Uint32(block[4:]),
		binary.LittleEndian.Uint32(block[8:]),
		binary.LittleEndian.Uint32(block[12:]),
		binary.LittleEndian.Uint32(block[16:]),
		binary.LittleEndian.Uint32(block[20:]),
		binary.LittleEndian.Uint32(block[24:]),
		binary.LittleEndian.Uint32(block[28:]),
		binary.LittleEndian.Uint32(block[32:]),
		binary.LittleEndian.Uint32(block[36:]),
		binary.LittleEndian.Uint32(block[40:]),
		binary.LittleEndian.Uint32(block[44:]),
		binary.LittleEndian.Uint32(block[48:]),
		binary.LittleEndian.Uint32(block[52:]),
		binary.LittleEndian.Uint32(block[56:]),
		binary.LittleEndian.Uint32(block[60:]),

		a, b, c, d, e := ctx.h[0], ctx.h[1], ctx.h[2], ctx.h[3], ctx.h[4]`,
	)

	for r := range 4 {
		round(w, r)
	}

	fmt.Fprintln(
		w,
		`

	ctx.h[0] += a
	ctx.h[1] += b
	ctx.h[2] += c
	ctx.h[3] += d
	ctx.h[4] += e
}`,
	)
}
